--
-- Triggers `partners`
--
DELIMITER $$
CREATE TRIGGER `before_partner_insert` BEFORE INSERT ON `partners` FOR EACH ROW BEGIN
    DECLARE next_num INT;
    
    IF NEW.partner_id IS NULL OR NEW.partner_id = '' THEN
        
        SELECT COALESCE(MAX(CAST(SUBSTRING(partner_id, 6) AS UNSIGNED)), 0) + 1 
        INTO next_num
        FROM partners 
        WHERE partner_id REGEXP '^ORG-[0-9]+$';
        
        SET NEW.partner_id = CONCAT('ORG-', LPAD(next_num, 4, '0'));
    END IF;
    
    IF NEW.created_at IS NULL THEN
        SET NEW.created_at = NOW();
    END IF;
    IF NEW.updated_at IS NULL THEN
        SET NEW.updated_at = NOW();
    END IF;
END
$$
DELIMITER ;

