-- Structure for view `v_rejected_centers_full`
--
DROP TABLE IF EXISTS `v_rejected_centers_full`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_rejected_centers_full`  AS SELECT `uc`.`id` AS `id`, `uc`.`data_upload_id` AS `data_upload_id`, `uc`.`partner_id` AS `partner_id`, `uc`.`data_upload_version` AS `data_upload_version`, `uc`.`center_name` AS `center_name`, `uc`.`city` AS `city`, `uc`.`state` AS `state`, `uc`.`review_status` AS `review_status`, `uc`.`rejection_reason` AS `rejection_reason`, `uc`.`rejection_remarks` AS `rejection_remarks`, `uc`.`reviewed_by` AS `reviewed_by`, `uc`.`reviewed_at` AS `reviewed_at`, `du`.`file_name` AS `file_name`, `du`.`version` AS `upload_version`, `p`.`name` AS `partner_name`, `u`.`full_name` AS `reviewed_by_name`, count(distinct `us`.`id`) AS `student_count`, sum(case when `us`.`is_edited` = 1 then 1 else 0 end) AS `edited_student_count` FROM ((((`uploaded_centers` `uc` join `data_uploads` `du` on(`uc`.`data_upload_id` = `du`.`id`)) join `partners` `p` on(`uc`.`partner_id` = `p`.`id`)) left join `users` `u` on(`uc`.`reviewed_by` = `u`.`id`)) left join `uploaded_students` `us` on(`us`.`uploaded_center_id` = `uc`.`id`)) WHERE `uc`.`review_status` = 'rejected' GROUP BY `uc`.`id`, `uc`.`data_upload_id`, `uc`.`partner_id`, `uc`.`data_upload_version`, `uc`.`center_name`, `uc`.`city`, `uc`.`state`, `uc`.`review_status`, `uc`.`rejection_reason`, `uc`.`rejection_remarks`, `uc`.`reviewed_by`, `uc`.`reviewed_at`, `du`.`file_name`, `du`.`version`, `p`.`name`, `u`.`full_name` ;

