-- Structure for view `v_upload_summary`
--
DROP TABLE IF EXISTS `v_upload_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_upload_summary`  AS SELECT `du`.`id` AS `id`, `du`.`partner_id` AS `partner_id`, `du`.`file_name` AS `file_name`, `du`.`version` AS `version`, `du`.`parent_upload_id` AS `parent_upload_id`, `du`.`centers_total` AS `centers_total`, `du`.`centers_reviewed` AS `centers_reviewed`, `du`.`centers_approved` AS `centers_approved`, `du`.`centers_rejected` AS `centers_rejected`, `du`.`review_progress` AS `review_progress`, `du`.`status` AS `status`, `du`.`created_at` AS `created_at`, `p`.`name` AS `partner_name`, `u`.`full_name` AS `uploaded_by_name`, CASE WHEN `du`.`version` > 1 THEN concat('Version ',`du`.`version`,' (Resubmission)') ELSE 'Version 1 (Original)' END AS `version_label` FROM ((`data_uploads` `du` join `partners` `p` on(`du`.`partner_id` = `p`.`id`)) left join `users` `u` on(`du`.`uploaded_by` = `u`.`id`)) ;

