INSERT INTO `courses` (`id`, `course_name`, `course_code`, `description`, `duration_months`, `is_active`, `created_at`, `updated_at`) VALUES
('6275ba97-c89b-11f0-94bf-00410e2b5e6e', 'Basic Electrican', 'ELEC-001', 'Comprehensive training in electrical installations, wiring, circuit design, and maintenance. Covers residential and industrial electrical systems, safety protocols, and troubleshooting techniques.', 6, 1, '2025-11-23 18:36:54', '2025-12-16 05:08:25'),
('6276774f-c89b-11f0-94bf-00410e2b5e6e', 'Solar Solution', 'SOLR-001', 'Specialized training in solar photovoltaic systems, panel installation, inverter configuration, and maintenance. Includes grid-tied and off-grid system design, energy efficiency, and renewable energy fundamentals.', 6, 1, '2025-11-23 18:36:54', '2025-12-16 05:08:31'),
('6276796c-c89b-11f0-94bf-00410e2b5e6e', 'Industrial Automation', 'IAUT-001', 'Advanced training in industrial automation systems, PLC programming, SCADA systems, and robotics. Covers sensor integration, control systems, industrial communication protocols, and automated manufacturing processes.', 6, 1, '2025-11-23 18:36:54', '2025-11-23 18:36:54');
